css_variables:
:root {
  --color-primary: #0B1F3A;
  --color-secondary: #1F3A5F;
  --color-accent: #06B6D4;
  --color-highlight: #EEF4FF;
  --color-bg: #FFFFFF;
  --color-text: #0B1220;
  --color-text-muted: #6B7280;
  --color-border: #E5E7EB;
  --font-heading: 'Space Grotesk', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif;
  --font-body: 'Inter', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif;
  --font-size-display: 58px;
  --font-size-h1: 40px;
  --font-size-h2: 32px;
  --font-size-h3: 24px;
  --font-size-h4: 20px;
  --font-size-body: 16px;
  --font-size-small: 13px;
  --font-weight-heading: 700;
  --font-weight-body: 400;
  --line-height-body: 1.7;
  --border-radius: 8px;
  --shadow-card: 0 1px 3px rgba(0,0,0,0.10), 0 2px 6px rgba(0,0,0,0.06);
}
